dependencies {
    implementation 'org.tensorflow:tensorflow-lite:2.14.0'
    // For GPU delegate:
    implementation 'org.tensorflow:tensorflow-lite-gpu:2.14.0'
    // For support library (optional):
    implementation 'org.tensorflow:tensorflow-lite-support:2.14.0'
}

// Preprocess bitmap to 28x28 grayscale float array
val bitmap = Bitmap.createScaledBitmap(inputBitmap, 28, 28, true)
val input = Array(1) { Array(28) { FloatArray(28) } }
for (y in 0 until 28) {
    for (x in 0 until 28) {
        val pixel = bitmap.getPixel(x, y)
        input[0][y][x] = (Color.red(pixel) / 255.0f)
    }
}

val output = Array(1) { FloatArray(10) }
interpreter.run(input, output)
val predictedDigit = output[0].indices.maxByOrNull { output[0][it] } ?: -1
println("Predicted digit: $predictedDigit")
